import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"Migration from Bull to BullMQ","description":"Tips and hints on how to migrate from Bull package to BullMQ.","frontmatter":{"description":"Tips and hints on how to migrate from Bull package to BullMQ."},"headers":[],"relativePath":"guide/migrations/bull-to-bullmq.md","filePath":"guide/migrations/bull-to-bullmq.md","lastUpdated":1785480634000}`),a={name:`guide/migrations/bull-to-bullmq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="migration-from-bull-to-bullmq" tabindex="-1">Migration from Bull to BullMQ <a class="header-anchor" href="#migration-from-bull-to-bullmq" aria-label="Permalink to “Migration from Bull to BullMQ”">​</a></h1><p>Bull and BullMQ have diverged too much now to actually give any guarantee of backwards compatibility.</p><p>So the safest would be to use new queues for BullMQ and deprecate the old ones.</p><p>New queues in this context mean using different queue names or passing a custom prefix option. You can have a period where bull and bullmq workers are running in parallel until all the jobs from the old queues are completed. Take into account that producers should add jobs in bullmq queues in this period. When all queues from bull are drained, you can deprecate them.</p><p>You can use a dashboard tool such as <a href="https://taskforce.sh" target="_blank" rel="noreferrer">https://taskforce.sh</a> for monitoring this process and make sure the old queues are completely empty before removing them.</p><h2 id="read-more" tabindex="-1">Read more: <a class="header-anchor" href="#read-more" aria-label="Permalink to “Read more:”">​</a></h2><ul><li>💡 <a href="https://docs.bullmq.io/api/interfaces/v6.WorkerOptions.html#prefix" target="_blank" rel="noreferrer">Worker Prefix Option Reference</a></li><li>💡 <a href="https://docs.bullmq.io/api/interfaces/v6.QueueOptions.html#prefix" target="_blank" rel="noreferrer">Queue Prefix Option Reference</a></li></ul>`,7)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};